using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;
class ConnectionUiTests {
 static int checks,failures;static void Check(bool ok,string n){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);}
 static IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var v in Find<T>(VisualTreeHelper.GetChild(root,i)))yield return v;}
 [STAThread]static int Main(string[] args){var app=new Application();Window window=null;string folder=AppDomain.CurrentDomain.BaseDirectory;try{var runtime=new AssistantRuntime(folder,folder);runtime.Config.Monitor.TaskbarItems=new List<string>{"cpu"};Check(!ConnectionStatus.Inspect(runtime).NeedsAttention,"unused quota and temperature features do not prompt");runtime.Config.Monitor.TaskbarItems.Add("codex5h");var state=ConnectionStatus.Inspect(runtime);Check(state.QuotaIssue!=null,"missing quota grant is detected before automatic execution");runtime.Telemetry.Dispose();
 bool saved=true,quota=false;var dialog=new ConnectionWindow(new ConnectionStatus{QuotaIssue="尚未授权",SensorIssue="采集器未运行"},folder,"a",true,v=>saved=v,()=>quota=true,()=>{});window=dialog;dialog.Show();dialog.UpdateLayout();Check(Find<Button>(dialog).Any(b=>Convert.ToString(b.Content)=="启动本机温度采集器（Windows UAC）"),"startup prompt offers explicit UAC action without running it");Check(Find<TextBox>(dialog).Any(t=>t.IsReadOnly&&t.Text==folder),"current local data location is selectable");var prompt=Find<CheckBox>(dialog).Single();prompt.IsChecked=false;prompt.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Check(!saved,"startup prompt preference changes only on user action");
 var image=new RenderTargetBitmap((int)dialog.ActualWidth,(int)dialog.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(dialog);using(var file=File.Create(Path.Combine(args[0],"local-connections-native.png"))){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));encoder.Save(file);}Find<Button>(dialog).Single(b=>Convert.ToString(b.Content)=="前往额度授权").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(quota&&!dialog.IsVisible,"quota action closes prompt and navigates to authorization");
 string provider=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ConanDesktopAssistant","components","LibreHardwareMonitor-v0.9.6");using(SensorProvider.Verify(provider)){Check(true,"official per-user sensor files match embedded pinned hashes");}bool rejected=false;try{using(SensorProvider.Verify(folder)){}}catch(IOException){rejected=true;}Check(rejected,"missing or replaced provider cannot trigger UAC");
 }catch(Exception e){failures++;Console.WriteLine(e);}finally{if(window!=null)window.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"connection-ui-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,driver_started=false,actual_grant_created=false}));return failures==0?0:1;}
}
